BEGIN;
CREATE TABLE IF NOT EXISTS tenants (
 id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE,
 status VARCHAR(32) NOT NULL DEFAULT 'active', plan_id BIGINT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS users (
 id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
 email VARCHAR(254) NOT NULL, name VARCHAR(160) NOT NULL, password_hash TEXT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'active',
 is_owner BOOLEAN NOT NULL DEFAULT FALSE, is_super_admin BOOLEAN NOT NULL DEFAULT FALSE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tenant_id,email)
);
CREATE UNIQUE INDEX IF NOT EXISTS users_email_global_idx ON users(lower(email));
CREATE TABLE IF NOT EXISTS roles (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,code VARCHAR(100) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS permissions (id BIGSERIAL PRIMARY KEY,code VARCHAR(140) NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS user_roles (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,permission_id BIGINT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS sessions (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,token_hash VARCHAR(255) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS sessions_exp_idx ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS exchange_accounts (
 id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,exchange VARCHAR(40) NOT NULL DEFAULT 'binance',label VARCHAR(120) NOT NULL,
 account_uid VARCHAR(120) NOT NULL DEFAULT '',p2p_nickname VARCHAR(160) NOT NULL DEFAULT '',api_key_ciphertext TEXT NOT NULL DEFAULT '',api_secret_ciphertext TEXT NOT NULL DEFAULT '',
 status VARCHAR(32) NOT NULL DEFAULT 'active',last_sync_at TIMESTAMPTZ NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,exchange,label)
);
CREATE INDEX IF NOT EXISTS exchange_accounts_tenant_idx ON exchange_accounts(tenant_id,status);
CREATE TABLE IF NOT EXISTS exchange_account_permissions (tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,exchange_account_id BIGINT NOT NULL REFERENCES exchange_accounts(id) ON DELETE CASCADE,permission_code VARCHAR(140) NOT NULL,PRIMARY KEY(user_id,exchange_account_id,permission_code));
CREATE TABLE IF NOT EXISTS orders (
 id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,exchange_account_id BIGINT NOT NULL REFERENCES exchange_accounts(id) ON DELETE CASCADE,
 external_order_no VARCHAR(100) NOT NULL,status VARCHAR(60) NOT NULL,trade_type VARCHAR(16) NOT NULL DEFAULT '',asset VARCHAR(32) NOT NULL DEFAULT '',fiat VARCHAR(32) NOT NULL DEFAULT '',price NUMERIC(28,12) NOT NULL DEFAULT 0,amount NUMERIC(28,12) NOT NULL DEFAULT 0,total NUMERIC(28,12) NOT NULL DEFAULT 0,
 counterparty_name VARCHAR(160) NOT NULL DEFAULT '',assigned_user_id BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,raw_json JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,exchange_account_id,external_order_no)
);
CREATE INDEX IF NOT EXISTS orders_tenant_status_idx ON orders(tenant_id,status,updated_at DESC);
CREATE INDEX IF NOT EXISTS orders_account_status_idx ON orders(exchange_account_id,status,updated_at DESC);
CREATE TABLE IF NOT EXISTS advertisements (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,exchange_account_id BIGINT NOT NULL REFERENCES exchange_accounts(id) ON DELETE CASCADE,external_adv_no VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,trade_type VARCHAR(16) NOT NULL DEFAULT '',asset VARCHAR(32) NOT NULL DEFAULT '',fiat VARCHAR(32) NOT NULL DEFAULT '',price NUMERIC(28,12) NOT NULL DEFAULT 0,surplus_amount NUMERIC(28,12) NOT NULL DEFAULT 0,raw_json JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,exchange_account_id,external_adv_no));
CREATE INDEX IF NOT EXISTS ads_tenant_idx ON advertisements(tenant_id,status,updated_at DESC);
CREATE TABLE IF NOT EXISTS chats (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,exchange_account_id BIGINT NOT NULL REFERENCES exchange_accounts(id) ON DELETE CASCADE,order_id BIGINT NULL REFERENCES orders(id) ON DELETE CASCADE,external_message_id VARCHAR(120) NOT NULL DEFAULT '',external_uuid VARCHAR(120) NOT NULL DEFAULT '',message_type VARCHAR(32) NOT NULL DEFAULT 'text',content TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',sender_name VARCHAR(160) NOT NULL DEFAULT '',is_self BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(32) NOT NULL DEFAULT 'unread',sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS chats_order_idx ON chats(tenant_id,order_id,sent_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS chat_read_states (tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,last_read_chat_id BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(user_id,order_id));
CREATE TABLE IF NOT EXISTS payment_accounts (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,name VARCHAR(160) NOT NULL,method_identifier VARCHAR(100) NOT NULL,account_name VARCHAR(180) NOT NULL DEFAULT '',account_number VARCHAR(180) NOT NULL DEFAULT '',bank_name VARCHAR(180) NOT NULL DEFAULT '',details_json JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(32) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS payment_accounts_tenant_idx ON payment_accounts(tenant_id,status);
CREATE TABLE IF NOT EXISTS routing_rules (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name VARCHAR(180) NOT NULL,priority INTEGER NOT NULL DEFAULT 100,enabled BOOLEAN NOT NULL DEFAULT TRUE,conditions_json JSONB NOT NULL DEFAULT '{}'::jsonb,actions_json JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ledger_accounts (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,code VARCHAR(80) NOT NULL,name VARCHAR(180) NOT NULL,account_type VARCHAR(40) NOT NULL,currency VARCHAR(20) NOT NULL DEFAULT 'USDT',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS ledger_transactions (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,reference_type VARCHAR(60) NOT NULL DEFAULT '',reference_id VARCHAR(120) NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',posted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ledger_entries (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,transaction_id BIGINT NOT NULL REFERENCES ledger_transactions(id) ON DELETE CASCADE,account_id BIGINT NOT NULL REFERENCES ledger_accounts(id),direction VARCHAR(6) NOT NULL CHECK(direction IN ('debit','credit')),amount NUMERIC(28,12) NOT NULL CHECK(amount>=0),currency VARCHAR(20) NOT NULL DEFAULT 'USDT',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ledger_entries_tx_idx ON ledger_entries(tenant_id,transaction_id);
CREATE TABLE IF NOT EXISTS notifications (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id BIGINT NULL REFERENCES users(id) ON DELETE CASCADE,kind VARCHAR(80) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL DEFAULT '',data_json JSONB NOT NULL DEFAULT '{}'::jsonb,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(tenant_id,user_id,is_read,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NULL REFERENCES tenants(id) ON DELETE SET NULL,user_id BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,action VARCHAR(140) NOT NULL,entity_type VARCHAR(100) NOT NULL DEFAULT '',entity_id VARCHAR(120) NOT NULL DEFAULT '',ip_address VARCHAR(80) NOT NULL DEFAULT '',user_agent TEXT NOT NULL DEFAULT '',metadata_json JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS audit_tenant_time_idx ON audit_logs(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS plans (id BIGSERIAL PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,monthly_price NUMERIC(18,2) NOT NULL DEFAULT 0,setup_fee NUMERIC(18,2) NOT NULL DEFAULT 0,max_users BIGINT NOT NULL DEFAULT 5,max_exchange_accounts BIGINT NOT NULL DEFAULT 2,entitlements_json JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(32) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS subscriptions (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,plan_id BIGINT NOT NULL REFERENCES plans(id),status VARCHAR(32) NOT NULL DEFAULT 'active',provider VARCHAR(60) NOT NULL DEFAULT 'manual',provider_subscription_id VARCHAR(180) NOT NULL DEFAULT '',current_period_start TIMESTAMPTZ NULL,current_period_end TIMESTAMPTZ NULL,cancel_at_period_end BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS subscriptions_tenant_idx ON subscriptions(tenant_id,status);
CREATE TABLE IF NOT EXISTS invoices (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,subscription_id BIGINT NULL REFERENCES subscriptions(id) ON DELETE SET NULL,invoice_type VARCHAR(32) NOT NULL DEFAULT 'monthly',currency VARCHAR(20) NOT NULL DEFAULT 'BDT',amount NUMERIC(18,2) NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL DEFAULT 'pending',due_at TIMESTAMPTZ NULL,paid_at TIMESTAMPTZ NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,invoice_id BIGINT NULL REFERENCES invoices(id) ON DELETE SET NULL,provider VARCHAR(60) NOT NULL,provider_payment_id VARCHAR(180) NOT NULL DEFAULT '',amount NUMERIC(18,2) NOT NULL DEFAULT 0,currency VARCHAR(20) NOT NULL DEFAULT 'BDT',status VARCHAR(32) NOT NULL DEFAULT 'pending',raw_json JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS approvals (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,requested_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,approved_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,kind VARCHAR(100) NOT NULL,payload_json JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(32) NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS proofs (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,order_id BIGINT NULL REFERENCES orders(id) ON DELETE CASCADE,uploaded_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,file_key TEXT NOT NULL,file_name TEXT NOT NULL,mime_type VARCHAR(120) NOT NULL DEFAULT '',size_bytes BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS activity_sessions (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_heartbeat_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),ended_at TIMESTAMPTZ NULL,status VARCHAR(32) NOT NULL DEFAULT 'online');
CREATE TABLE IF NOT EXISTS extension_tasks (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,exchange_account_id BIGINT NULL REFERENCES exchange_accounts(id) ON DELETE CASCADE,task_type VARCHAR(100) NOT NULL,payload_json JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(32) NOT NULL DEFAULT 'pending',attempt_count INTEGER NOT NULL DEFAULT 0,result_json JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS outbox_events (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NULL REFERENCES tenants(id) ON DELETE CASCADE,topic VARCHAR(140) NOT NULL,event_key VARCHAR(180) NOT NULL DEFAULT '',payload_json JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(32) NOT NULL DEFAULT 'pending',attempt_count INTEGER NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),published_at TIMESTAMPTZ NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS outbox_pending_idx ON outbox_events(status,available_at,id);
CREATE TABLE IF NOT EXISTS system_settings (id BIGSERIAL PRIMARY KEY,scope_type VARCHAR(40) NOT NULL,scope_id BIGINT NOT NULL DEFAULT 0,key VARCHAR(160) NOT NULL,value_json JSONB NOT NULL DEFAULT '{}'::jsonb,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(scope_type,scope_id,key));
INSERT INTO plans(code,name,monthly_price,setup_fee,max_users,max_exchange_accounts,entitlements_json,status)
VALUES ('starter','Starter',0,0,5,2,'{"orders":true,"ads":true,"chat":true}'::jsonb,'active') ON CONFLICT(code) DO NOTHING;
COMMIT;
